import { dirname } from 'path';
import { fileURLToPath } from 'url';
import { FlatCompat } from '@eslint/eslintrc';

const compat = new FlatCompat({ baseDirectory: dirname(fileURLToPath(import.meta.url)) });

const config = [
  ...compat.extends('next/core-web-vitals', 'next/typescript'),
  // next-env.d.ts is generated by Next on every build; its triple-slash
  // reference is not ours to fix.
  { ignores: ['.next/**', 'node_modules/**', 'scripts/**', 'next-env.d.ts'] },
  {
    rules: {
      // Instagram's CDN URLs are signed and short-lived, so next/image's optimiser
      // (which caches by URL) is the wrong tool — plain <img> is deliberate.
      '@next/next/no-img-element': 'off',
    },
  },
];

export default config;
